-- PostgreSQL 16+. Import the complete Phong Vũ category snapshot.
BEGIN;
CREATE TABLE IF NOT EXISTS phongvu_catalog_snapshot (
    observed_on DATE NOT NULL,
    seller_sku TEXT NOT NULL,
    category TEXT NOT NULL CHECK (category IN ('laptop', 'phone', 'tablet')),
    brand TEXT NOT NULL,
    product_name TEXT NOT NULL,
    model_slug TEXT,
    verified_release_year INTEGER,
    announcement_date DATE,
    date_basis TEXT,
    launch_source_url TEXT,
    observed_price_vnd BIGINT CHECK (observed_price_vnd > 0),
    observed_list_price_vnd BIGINT CHECK (observed_list_price_vnd > 0),
    store_status TEXT NOT NULL CHECK (store_status IN ('Thêm vào giỏ', 'Liên hệ')),
    ram_gb INTEGER CHECK (ram_gb > 0),
    storage_gb INTEGER CHECK (storage_gb > 0),
    seller_product_url TEXT NOT NULL,
    image_url TEXT NOT NULL,
    local_image_path TEXT,
    category_source_url TEXT NOT NULL,
    card_text_json JSONB NOT NULL,
    detail_specs_json JSONB NOT NULL,
    PRIMARY KEY (observed_on, seller_sku),
    CHECK (
        (verified_release_year IS NULL AND model_slug IS NULL AND announcement_date IS NULL AND date_basis IS NULL AND launch_source_url IS NULL)
        OR
        (verified_release_year IS NOT NULL AND model_slug IS NOT NULL AND announcement_date IS NOT NULL AND date_basis IS NOT NULL AND launch_source_url IS NOT NULL)
    )
);
CREATE INDEX IF NOT EXISTS idx_phongvu_snapshot_category_year
    ON phongvu_catalog_snapshot (observed_on, category, verified_release_year);

INSERT INTO phongvu_catalog_snapshot (
    observed_on, seller_sku, category, brand, product_name, model_slug, verified_release_year, announcement_date, date_basis, launch_source_url, observed_price_vnd, observed_list_price_vnd, store_status, ram_gb, storage_gb, seller_product_url, image_url, local_image_path, category_source_url, card_text_json, detail_specs_json
)
